import sys

def has_self_intersections(n, points):
    points.sort()
    for i in range(n - 1):
        for j in range(i + 2, n):
            mid1 = (points[i] + points[i + 1]) / 2
            mid2 = (points[j] + points[j - 1]) / 2
            radius1 = abs(points[i] - points[i + 1]) / 2
            radius2 = abs(points[j] - points[j - 1]) / 2
            if abs(mid1 - mid2) < radius1 + radius2:
                return "yes"
    return "no"

if __name__ == "__main__":
    n = int(sys.stdin.readline())
    points = list(map(int, sys.stdin.readline().split()))
    print(has_self_intersections(n, points))
